#[derive(Clone,Copy,Default)] struct Node{left:i32,right:i32,rep:usize,mask:u64,cx:f64,cy:f64,r:f64,span:f64}
struct Ctx{x:[f64;8],y:[f64;8],nodes:[Node;15],used:usize,n:usize,sep:f64,edges:[f64;56],ec:usize}
fn point_less(c:&Ctx,a:usize,b:usize,axis:usize)->bool{let (a0,b0,a1,b1)=if axis==0{(c.x[a],c.x[b],c.y[a],c.y[b])}else{(c.y[a],c.y[b],c.x[a],c.x[b])};a0<b0||(a0==b0&&(a1<b1||(a1==b1&&a<b)))}
fn build(c:&mut Ctx,mask:u64)->usize{let at=c.used;c.used+=1;let mut ids=[0usize;8];let mut n=0;let mut rep=8;let(mut xmin,mut xmax,mut ymin,mut ymax)=(0.0,0.0,0.0,0.0);for i in 0..c.n{if mask&(1u64<<i)!=0{if n==0{xmin=c.x[i];xmax=xmin;ymin=c.y[i];ymax=ymin}else{xmin=xmin.min(c.x[i]);xmax=xmax.max(c.x[i]);ymin=ymin.min(c.y[i]);ymax=ymax.max(c.y[i]);}ids[n]=i;n+=1;rep=rep.min(i);}}let cx=(xmin+xmax)/2.0;let cy=(ymin+ymax)/2.0;let rx=(xmax-xmin)/2.0;let ry=(ymax-ymin)/2.0;c.nodes[at]=Node{left:-1,right:-1,rep,mask,cx,cy,r:rx.hypot(ry),span:(xmax-xmin).max(ymax-ymin)};if n==1{return at}let axis=if xmax-xmin>=ymax-ymin{0}else{1};for i in 1..n{let v=ids[i];let mut j=i;while j>0&&point_less(c,v,ids[j-1],axis){ids[j]=ids[j-1];j-=1;}ids[j]=v;}let mut lm=0u64;let mut rm=0u64;for i in 0..n{if i<n/2{lm|=1u64<<ids[i]}else{rm|=1u64<<ids[i]}}let l=build(c,lm);let r=build(c,rm);c.nodes[at].left=l as i32;c.nodes[at].right=r as i32;at}
fn separated(c:&Ctx,a:usize,b:usize)->bool{let u=c.nodes[a];let v=c.nodes[b];(u.cx-v.cx).hypot(u.cy-v.cy)-u.r-v.r>=c.sep*u.r.max(v.r)}
fn cross_nodes(c:&mut Ctx,a:usize,b:usize){if separated(c,a,b){let(mut u,mut v)=(c.nodes[a].rep,c.nodes[b].rep);if u>v{std::mem::swap(&mut u,&mut v)}let k=c.ec*2;c.edges[k]=u as f64;c.edges[k+1]=v as f64;c.ec+=1;return}let u=c.nodes[a];let v=c.nodes[b];if u.left<0{cross_nodes(c,v.left as usize,a);cross_nodes(c,v.right as usize,a)}else if v.left<0{cross_nodes(c,u.left as usize,b);cross_nodes(c,u.right as usize,b)}else if u.span>v.span{cross_nodes(c,u.left as usize,b);cross_nodes(c,u.right as usize,b)}else{cross_nodes(c,a,v.left as usize);cross_nodes(c,a,v.right as usize)}}
fn visit(c:&mut Ctx,at:usize){let n=c.nodes[at];if n.left<0{return}let l=n.left as usize;let r=n.right as usize;visit(c,l);visit(c,r);cross_nodes(c,l,r)}
#[no_mangle] pub unsafe extern "C" fn euclidean_t_spanner(input:*const f64,len:usize,output:*mut f64,cap:usize)->i64{if input.is_null()||len<6||len>18{return -1}let v=std::slice::from_raw_parts(input,len);if !v[0].is_finite()||v[0]<2.0||v[0]>8.0||v[0]!=v[0].floor()||!v[1].is_finite()||!(1.5..=4.0).contains(&v[1]){return -1}let n=v[0] as usize;if len!=2+2*n{return -1}let mut c=Ctx{x:[0.0;8],y:[0.0;8],nodes:[Node::default();15],used:0,n,sep:4.0*(v[1]+1.0)/(v[1]-1.0),edges:[0.0;56],ec:0};for i in 0..n{let x=v[2+2*i];let y=v[3+2*i];if !x.is_finite()||!y.is_finite()||x.abs()>1000.0||y.abs()>1000.0||x!=x.trunc()||y!=y.trunc(){return -1}for j in 0..i{if c.x[j]==x&&c.y[j]==y{return -1}}c.x[i]=x;c.y[i]=y}let root=build(&mut c,(1u64<<n)-1);visit(&mut c,root);let needed=1+2*c.ec;if output.is_null()||cap<needed{return -2}let o=std::slice::from_raw_parts_mut(output,cap);o[..needed].copy_from_slice(&[c.ec as f64]);for i in 0..2*c.ec{o[i+1]=c.edges[i]}needed as i64}
